import {make} from './factory.js';
export default [
make('PRE',1,{t:'Harf, tovush va ismni harflab aytish',goal:'Ismingizni harflab aytasiz va harf nomi bilan tovushni farqlaysiz.',context:'Yangi o‘quvchi kursga yozilayotganda kotib uning ismini aniqlashtiradi.',rule:['Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/.','A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq.','Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.'],pattern:'My name is … / How do you spell it? / A — L — I',ex:['My name is Ali.','How do you spell it?','A is a letter.','B is the first letter in bag.','Please spell your name.','L — O — L — A.'],v:['name|ism|/neɪm/|my name','letter|harf|/ˈletə/|a capital letter','spell|harflab aytmoq|/spel/|spell a name','bag|sumka|/bæɡ/|a school bag'],read:'My name is Ali. I am a new student. My name has three letters: A, L and I. Lola is in my class. Her name has four letters. We write our names with a capital letter at the beginning.',rq:[['Ali ismi nechta harfdan iborat?','three','four','five','Matnda A, L, I — uch harf aytilgan.'],['Qaysi ism to‘rt harfdan iborat?','Lola','Ali','I','Lola ismi L, O, L, A shaklida yoziladi.']],evidence:['Ali ismi uch harf ekaniga dalilni tanlang.',2,'Three letters jumlasi bevosita dalil.'],listen:'Hello. My name is Lola. Please write my name: L, O, L, A. Ali is my friend. His name is A, L, I.',lq:[['Yozuvdagi asosiy ism nima?','Lola','Lila','Lena','Yozuvda L, O, L, A deyiladi.'],['Lolaning do‘sti kim?','Ali','Aziz','Omar','His name is A, L, I jumlasiga quloq tuting.']],table:[['Asosiy ism','Lola'],['Do‘sti','Ali']],gap:'My ___ is Ali.|name',fix:'my name is ali.|My name is Ali.',mc:['Ismni harflab aytishni so‘rash uchun qaysi gap mos?','How do you spell it?','How old are you?','Where are you?','Spell harfma-harf aytishni bildiradi.'],exit:[['Ism: L — O — L — A. Yozing.','Lola'],['My ___ is Ali.','name'],['How do you ___ it?','spell'],['Ali ismi nechta harf?','three','four','six','A, L, I — uchta.'],['B harfining nomi va /b/ tovushi bir xilmi?','No','Yes','Always','Harf nomi bee, bag boshida tovush /b/.']],wtask:'Sherigingizga ismingizni va uni qanday harflashingizni ikki yoki uch gapda yozing.',write:'My name is Lola. My name has four letters. I spell it L, O, L, A.',speak:'Ismingizni ayting, uni harflang. Keyin sherigingizdan ismini harflab berishni so‘rang.',visual:'alphabet',pron:'B harfining bee nomini bag boshidagi qisqa /b/ tovushidan ajrating.'}),
make('PRE',2,{t:'Salomlashish va o‘zingizni tanishtirish',goal:'Qisqa salomlashasiz, ismingizni aytasiz va suhbatni yakunlaysiz.',context:'Ikki o‘quvchi yangi sinfda birinchi marta uchrashadi.',rule:['Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi.','I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi.','Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.'],pattern:'Hello. I’m … / Nice to meet you. / See you.',ex:['Hello. I am Lola.','Hi. I’m Ali.','Nice to meet you.','Good morning, teacher.','You are my classmate.','See you tomorrow.'],v:['hello|salom|/həˈləʊ/|say hello','teacher|o‘qituvchi|/ˈtiːtʃə/|my teacher','classmate|sinfdosh|/ˈklɑːsmeɪt/|a new classmate','tomorrow|ertaga|/təˈmɒrəʊ/|see you tomorrow'],read:'Hello. I am Lola. Ali is my new classmate. We meet at school in the morning. I say, “Good morning, Ali.” He says, “Hi, Lola. Nice to meet you.” At the end of the lesson, we say, “See you tomorrow.”',rq:[['O‘quvchilar qayerda uchrashadi?','at school','at home','at a shop','We meet at school — joy bevosita berilgan.'],['Qachon Good morning deyishadi?','in the morning','at night','after dinner','Uchrashuv ertalab bo‘lib o‘tadi.']],listen:'Good morning. I am your teacher. My name is Malika. This is your classmate, Ali. Please say hello. Nice to meet you, everyone.',lq:[['O‘qituvchining ismi nima?','Malika','Lola','Maya','My name is Malika deyiladi.'],['Sinfdoshning ismi nima?','Ali','Vali','Bob','This is your classmate, Ali deyiladi.']],table:[['O‘qituvchi','Malika'],['Sinfdosh','Ali']],gap:'Nice to ___ you.|meet',fix:'I is Lola.|I am Lola.|I’m Lola.',mc:['Ertalab o‘qituvchi bilan salomlashish uchun qaysi gap mos?','Good morning.','Good night.','Goodbye.','Morning ertalab degani.'],exit:[['I ___ Ali.','am'],['Nice to ___ you.','meet'],['See you ___.','tomorrow'],['I’m nimaning qisqartmasi?','I am','I is','I has','Apostrof tushirilgan harfni bildiradi.'],['Xayrlashish uchun gap tanlang.','Goodbye.','Nice to meet you.','What is it?','Goodbye suhbatni yakunlaydi.']],wtask:'Yangi sinfdoshingizga uch gapdan iborat tanishtirish xabarini yozing.',write:'Hello. I am Aziz. I am your new classmate. Nice to meet you.',speak:'Yangi sinfdosh bilan uchrashuvni o‘ynang: salomlashish, ism, javob va xayrlashish.',visual:'dialogue'}),
make('PRE',3,{t:'Sonlar, yosh va telefon raqami',goal:'0–100 oralig‘idagi sonlarni taniysiz, yosh va telefon raqamini aytasiz.',context:'Sport to‘garagi uchun yosh va aloqa ma’lumotlari yoziladi.',rule:['Yoshni I am twelve tarzida aytamiz. Inglizchada yosh uchun I have twelve demaymiz. Years old iborasi qo‘shilishi mumkin.','13–19 sonlarida -teen, 20, 30, 40 kabi o‘nliklarda -ty farqiga e’tibor bering. Thirteen va thirty bir xil emas.','Telefon raqamida har bir raqam alohida o‘qiladi. Zero nolning aniq nomidir; oh telefon raqamlarida ham uchraydi.'],pattern:'How old are you? / I am twelve. / zero, one, two …',ex:['I am twelve years old.','How old are you?','My brother is thirteen.','Thirty is three tens.','My number is one, two, zero, five.','There are ten students.'],v:['twelve|o‘n ikki|/twelv/|twelve years old','thirteen|o‘n uch|/ˌθɜːˈtiːn/|thirteen students','thirty|o‘ttiz|/ˈθɜːti/|thirty minutes','number|raqam yoki son|/ˈnʌmbə/|phone number'],read:'Aziz is twelve. His sister is thirteen. They join a sports club. There are thirty students at the club. The teacher writes their names and ages. Aziz gives a short practice number: one, two, zero, five. It is not his real phone number.',rq:[['Aziz necha yoshda?','twelve','thirteen','thirty','Aziz is twelve jumlasini tekshiring.'],['To‘garakda nechta o‘quvchi bor?','thirty','thirteen','twelve','Thirty o‘ttizni bildiradi.']],listen:'My name is Aziz. I am twelve years old. My sister is thirteen. Please write this practice number: one, two, zero, five. There are thirty students in our club.',lq:[['Azizning singlisi necha yoshda?','thirteen','thirty','three','Sister is thirteen — teen urg‘usini ajrating.'],['Mashq raqami qaysi?','1205','1250','1025','One, two, zero, five shu tartibda aytiladi.']],table:[['Azizning yoshi','twelve'],['Mashq raqami','1205']],gap:'I ___ twelve years old.|am',fix:'I have twelve years old.|I am twelve years old.',mc:['30 sonining nomini tanlang.','thirty','thirteen','three','Thirty — uchta o‘nlik.'],exit:[['12 sonini inglizcha yozing.','twelve'],['13 sonini inglizcha yozing.','thirteen'],['How ___ are you?','old'],['1, 2, 0, 5 ketma-ketligini tanlang.','1205','1250','1025','Raqam tartibi o‘zgarmaydi.'],['Yoshni to‘g‘ri ayting.','I am twelve.','I have twelve.','I twelve.','Yoshda to be ishlatiladi.']],wtask:'Xayoliy to‘garak uchun ism, yosh va to‘rt raqamli mashq raqami yozing. Haqiqiy telefoningizni kiritmang.',write:'My name is Lola. I am thirteen years old. My practice number is four, one, zero, two.',speak:'Yoshingizni va xayoliy to‘rt raqamli raqamni sekin ayting. Sherigingiz yozib olsin.',visual:'number',pron:'Thirteen so‘zida ikkinchi bo‘g‘in, thirty so‘zida birinchi bo‘g‘in ko‘proq urg‘u oladi.'}),
make('PRE',4,{t:'Sana, hafta kunlari va vaqt',goal:'Oddiy uchrashuvning kuni va vaqtini tushunasiz.',context:'Kutubxonadagi mashg‘ulotning jadvali e’lon qilinadi.',rule:['Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi.','It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir.','Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.'],pattern:'on Monday / at nine o’clock / It is nine thirty.',ex:['The lesson is on Monday.','We meet at nine o’clock.','It is nine thirty.','Friday is a school day.','The club starts at ten.','Today is Tuesday.'],v:['Monday|dushanba|/ˈmʌndeɪ/|on Monday','Friday|juma|/ˈfraɪdeɪ/|on Friday','today|bugun|/təˈdeɪ/|today is Tuesday','start|boshlanmoq|/stɑːt/|start at ten'],read:'The reading club meets on Monday. It starts at nine o’clock. On Friday, the club starts at nine thirty. Lola writes both times in her notebook. Today is Tuesday, so there is no club meeting today. The next meeting is on Friday.',rq:[['Dushanbadagi mashg‘ulot qachon boshlanadi?','nine o’clock','nine thirty','ten o’clock','Monday uchun nine o’clock yozilgan.'],['Keyingi uchrashuv qaysi kun?','Friday','Tuesday','Monday','The next meeting is on Friday.']],listen:'Hello, reading club. Our next meeting is on Friday at nine thirty. Please bring a notebook. Today is Tuesday. There is no meeting today.',lq:[['Uchrashuv kuni qaysi?','Friday','Tuesday','Sunday','Next meeting is on Friday deyiladi.'],['Uchrashuv soati qaysi?','9:30','9:00','10:30','Nine thirty — 9:30.']],table:[['Kun','Friday'],['Vaqt','9:30']],gap:'We meet ___ Monday.|on',fix:'The club starts on nine.|The club starts at nine.',mc:['Aniq soat oldidan qaysi predlog ishlatiladi?','at','on','in','At nine — aniq soat.'],exit:[['We meet ___ Friday.','on'],['The lesson starts ___ ten.','at'],['9:30 ni so‘z bilan yozing.','nine thirty'],['Kun nomining to‘g‘ri yozilishini tanlang.','Monday','monday','MONday','Kun nomi bosh harf bilan boshlanadi.'],['Today nimani anglatadi?','bugun','ertaga','kecha','Today hozirgi kun.']],wtask:'Sinf to‘garagi uchun kun, boshlanish soati va olib kelinadigan buyumni yozing.',write:'Our club is on Monday. We meet at ten o’clock. Please bring a notebook.',speak:'Uchrashuv kuni va vaqtini ayting. Sherigingizdan When? deb qayta so‘rang.',visual:'timetable'}),
make('PRE',5,{t:'Yo‘riqnomalar va gap bo‘laklari',goal:'Listen, read, write, choose buyruqlarini tushunasiz va ot, fe’l, sifatni ajratasiz.',context:'O‘qituvchi yangi mashqni tushuntiradi.',rule:['Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi.','Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is.','Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.'],pattern:'Ega → fe’l → to‘ldiruvchi / I → read → a book.',ex:['I read a book.','Please listen to the teacher.','Write your name.','Choose the blue book.','Ali is a student.','The small bag is blue.'],v:['read|o‘qimoq|/riːd/|read a book','write|yozmoq|/raɪt/|write a name','choose|tanlamoq|/tʃuːz/|choose a book','blue|ko‘k|/bluː/|a blue bag'],read:'The teacher says, “Read a book.” Ali chooses a small blue book. Lola writes her name in a notebook. Then they listen to the teacher. The teacher asks them to choose a picture. A book is a thing; read is an action; blue describes a colour.',rq:[['Ali qanday kitob tanlaydi?','a small blue book','a large red book','a green notebook','Small va blue kitobning belgilaridir.'],['Read qaysi vazifani bajaradi?','an action','a colour','a person','Read o‘qish amalini ifodalaydi.']],listen:'Please listen. Read the first sentence. Write your name. Then choose the blue book. Do not choose the red book. Thank you.',lq:[['Qaysi kitob tanlanadi?','blue','red','green','Choose the blue book deyiladi.'],['Nima yoziladi?','your name','a number','a colour','Write your name — ism yozish.']],table:[['Kitob rangi','blue'],['Yoziladigan ma’lumot','name']],gap:'I ___ a book.|read',fix:'Book I read a.|I read a book.',mc:['Blue qaysi gap bo‘lagi?','adjective','verb','pronoun','Blue kitobning rangini tasvirlaydi.'],exit:[['Yozing degan buyruqni inglizcha yozing.','write'],['I ___ a book.','read'],['___ the blue book.','Choose'],['Book qanday so‘z?','noun','verb','adverb','Book buyumni nomlaydi.'],['Oddiy gap tartibini tanlang.','I read a book.','Read I book a.','A I book read.','Ega avval, fe’l undan keyin.']],wtask:'Sherigingiz uchun uchta sodda mashq yo‘riqnomasini yozing.',write:'Read the sentence. Write your name. Choose the blue book.',speak:'Uch yo‘riqnomani ayting; sherigingiz bajarishini so‘rang. So‘ng rollarni almashtiring.',visual:'sentence'}),
make('PRE',6,{t:'O‘qish qoidalari va birinchi loyiha',goal:'Harf yozuvi va talaffuz bir xil emasligini misollarda ko‘rsatib, qisqa tanishtirasiz.',context:'Kursning birinchi haftasi yakunida har bir o‘quvchi o‘zini tanishtiradi.',rule:['Cat so‘zidagi a ko‘pincha /æ/, name so‘zidagi a esa /eɪ/ bo‘ladi. Oxirgi e ayrim so‘zlarda talaffuz qilinmasa ham oldingi unlini o‘zgartiradi. Bu har bir so‘z uchun mutlaq qoida emas.','/iː/ va /ɪ/ farqi sheep va ship kabi so‘zlarda ma’noni o‘zgartiradi. IPA talaffuzni aniqlashtiruvchi belgilar tizimidir.','Tanishtirishda ism, yosh, sinf va bitta qiziqishni mantiqiy tartibda ayting. Tushunmasangiz, Please say it again deb qayta so‘rashingiz mumkin.'],pattern:'cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/',ex:['My name is Aziz.','I am twelve years old.','I am in class six.','Please say it again.','This is a ship.','I like books.'],v:['ship|kema|/ʃɪp/|a big ship','sheep|qo‘y|/ʃiːp/|a white sheep','again|yana|/əˈɡen/|say it again','class|sinf|/klɑːs/|class six'],read:'My name is Aziz. I am twelve years old. I am in class six. I like books and pictures of ships. In our English lesson, I learn that ship and sheep are different words. When I do not understand a word, I ask, “Please say it again.”',rq:[['Aziz nechanchi sinfda?','class six','class five','class seven','I am in class six jumlasiga qarang.'],['Aziz tushunmasa nima qiladi?','asks to hear it again','closes the book','leaves the class','U qayta aytishni so‘raydi.']],listen:'Hello. My name is Aziz. I am twelve. I am in class six. I like books. I can spell my name: A, Z, I, Z. Please say your name again.',lq:[['Ism nechta harf bilan aytiladi?','four','three','five','A, Z, I, Z — to‘rtta harf.'],['Azizning qiziqishi nima?','books','football','music','I like books deyiladi.']],table:[['Sinf','six'],['Yosh','twelve']],gap:'Please say it ___.|again',fix:'My name Aziz.|My name is Aziz.',mc:['Ship va sheep haqida qaysi fikr to‘g‘ri?','Ular boshqa so‘zlar va tovushlari farq qiladi.','Ularning ma’nosi doim bir xil.','Ular faqat yozuvda farq qiladi.','/ɪ/ va /iː/ ikki turli unli tovush.'],exit:[['My name ___ Aziz.','is'],['I am in ___ six.','class'],['Please say it ___.','again'],['Cat va name dagi a har doim bir xil aytiladimi?','No','Yes','Only in names','Yozuv tovushni birga bir ifodalamaydi.'],['Sheep qanday hayvon?','qo‘y','kema','mushuk','Sheep /ʃiːp/ — qo‘y.']],wtask:'Birinchi loyiha: ism, yosh, sinf va qiziqishingiz haqida 4–5 gap yozing.',write:'My name is Lola. I am thirteen years old. I am in class seven. I like books. Nice to meet you.',speak:'O‘zingizni tanishtiring, ismingizni harflang va bitta savolga javob bering.',real:'Yangi mashqdagi noma’lum ko‘rsatmani qayta so‘rang va tushunganingizni sherigingizga ayting.',visual:'sound',pron:'Ship va sheep yozuvini solishtiring. /iː/ faqat cho‘zilish bilan emas, til holati bilan ham /ɪ/ dan farq qiladi.'})
];
